class PickerChecks{[STAThread]static void Main(){var a=Assembly.LoadFrom(@"C:\Jago Studio Dev\GitHub\Jago-Companion\Jago-Companion.exe");var t=a.GetType("ScreenColourPicker");int n=0;Action<bool> check=v=>{if(!v)throw new Exception("Failed check "+n);n++;};var flags=BindingFlags.Static|BindingFlags.NonPublic;check((string)t.GetMethod("Hex",flags).Invoke(null,new object[]{Color.FromArgb(12,34,255)})=="#0C22FF");foreach(var s in new[]{"#000000","#ffffff","#012ABC"})check((bool)t.GetMethod("ValidHex",flags).Invoke(null,new object[]{s}));foreach(var s in new[]{"red","#123","#GG0000","#000000\n"})check(!(bool)t.GetMethod("ValidHex",flags).Invoke(null,new object[]{s}));using(var bmp=new Bitmap(640,480)){bmp.SetPixel(30,40,Color.FromArgb(12,34,255));using(var f=(Form)Activator.CreateInstance(t,BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{bmp,new Rectangle(-640,0,640,480)},null)){check(f.Bounds.Left==-640);t.GetMethod("OnMouseMove",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{new MouseEventArgs(MouseButtons.None,0,100,100,0)});using(var render=new Bitmap(640,480)){using(var g=Graphics.FromImage(render))t.GetMethod("OnPaint",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{new PaintEventArgs(g,new Rectangle(0,0,640,480))});render.Save(@"C:\Jago Studio Dev\work\Colour-Picker\picker.png");}t.GetMethod("OnMouseDown",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{new MouseEventArgs(MouseButtons.Left,1,30,40,0)});check(f.DialogResult==DialogResult.OK);check(((Color)t.GetField("Chosen",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f)).ToArgb()==Color.FromArgb(12,34,255).ToArgb());}using(var f=(Form)Activator.CreateInstance(t,BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{bmp,new Rectangle(0,0,640,480)},null)){t.GetMethod("OnMouseMove",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{new MouseEventArgs(MouseButtons.None,0,100,100,0)});using(var render=new Bitmap(640,480)){using(var g=Graphics.FromImage(render))t.GetMethod("OnPaint",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{new PaintEventArgs(g,new Rectangle(0,0,640,480))});render.Save(@"C:\Jago Studio Dev\work\Colour-Picker\picker.png");}t.GetMethod("OnMouseDown",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{new MouseEventArgs(MouseButtons.Right,1,0,0,0)});check(f.DialogResult==DialogResult.Cancel);}}Console.WriteLine(n+" colour picker checks passed");}}
